    void testNode_WhenWholeCollectionAndNodeTypeTest_NodeTypeNode_ReturnsTrue() {
        NodeTypeTest nodeTypeTest = mock(NodeTypeTest.class);
        when(nodeTypeTest.getNodeType()).thenReturn(Compiler.NODE_TYPE_NODE);

        boolean result = collectionPointerWhole.testNode(nodeTypeTest);
        assertTrue(result);
