        NodeTest mockTest = mock(NodeTest.class);
        NodePointer mockValuePointer = mock(NodePointer.class);

        when(mockValuePointer.testNode(mockTest)).thenReturn(true);

        CollectionPointer spyPointer = spy(collectionPointerIndexed);
        doReturn(mockValuePointer).when(spyPointer).getValuePointer();

        boolean result = spyPointer.testNode(mockTest);
        assertTrue(result);
        verify(mockValuePointer).testNode(mockTest);
    }

    @Test
    void testNode_WhenWholeCollectionAndOtherTestType_ReturnsFalse() {
        NodeTest otherTest = mock(NodeTest.class);

        boolean result = collectionPointerWhole.testNode(otherTest);
        assertFalse(result);
    }

    private static Stream<Arguments> provideWholeCollectionTestCases() {
        return Stream.of(
            Arguments.of(null, true),
            Arguments.of(mock(NodeNameTest.class), false),
            Arguments.of(createNodeTypeTest(Compiler.NODE_TYPE_NODE), true),
            Arguments.of(createNodeTypeTest(Compiler.NODE_TYPE_TEXT), false),
            Arguments.of(createNodeTypeTest(Compiler.NODE_TYPE_COMMENT), false),
            Arguments.of(mock(NodeTest.class), false)
        );
    }

    @ParameterizedTest
    @MethodSource("provideWholeCollectionTestCases")
    void testNode_WholeCollection_VariousTests(NodeTest test, boolean expected) {
