        CollectionPointer spyPointer = spy(collectionPointerIndexed);
        doReturn(mockValuePointer).when(spyPointer).getValuePointer();

        boolean result = spyPointer.testNode(null);
        assertTrue(result);
    }

    private static NodeTypeTest createNodeTypeTest(int nodeType) {
        NodeTypeTest test = mock(NodeTypeTest.class);
        when(test.getNodeType()).thenReturn(nodeType);
        return test;
    }
